import AxeBuilder from '@axe-core/playwright';
import assert from 'node:assert/strict';import {readFile,writeFile,mkdtemp,cp,rm} from 'node:fs/promises';import path from 'node:path';import {tmpdir} from 'node:os';import {chromium} from 'playwright';import {verificationScreenshot} from '../../engine/verify-screenshot.mjs';import {verifyNavigation} from '../../engine/verify-navigation.mjs';import {visualScore} from '../../engine/verify.mjs';import {serveStatic} from '../../engine/static.mjs';import {run} from '../../engine/pipeline.mjs';
const root=path.resolve('work/uae'),artifact=path.resolve(process.argv[2]||'artifacts/platform/ultimate-variants-installed'),records=JSON.parse(await readFile(path.join(root,'ultimate-menu-variant-records.json'))),temp=await mkdtemp(path.join(tmpdir(),'ultimate-variants-')),results=[],sourceChecks=JSON.parse(await readFile(path.join(root,'ultimate-variants-source-check.json')));let browser,server;
try{await cp(path.join(artifact,'project'),temp,{recursive:true});for(const name of ['component-addon-navigation.js','component-export.mjs','component-markup.mjs'])await cp(new URL('../../scripts/'+name,import.meta.url),path.join(temp,'scripts',name));await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
for(const record of records.filter(r=>!process.env.VARIANT||r.variant===process.env.VARIANT))for(const width of (process.env.WIDTH?[Number(process.env.WIDTH)]:[1440,390])){
 const context=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),page=await context.newPage();page.setDefaultTimeout(12000);await page.goto(server.url+new URL(record.url).pathname,{waitUntil:'networkidle'});const widget=page.locator('.elementor-widget-navigation-menu'),flyout=record.settings.layout==='flyout',pixels={};
 const screenshot=async state=>{const name='variant-'+record.variant+'-'+width+'-'+state+'.png',file=path.join(artifact,name);await verificationScreenshot(page,file);pixels[state]=visualScore(await readFile(path.join(root,name)),await readFile(file));assert.ok(pixels[state]>=.99,'Visual mismatch '+record.variant+' '+width+' '+state+': '+pixels[state]);};await screenshot('closed');
 const toggle=widget.locator('.hfe-nav-menu__toggle');if(await toggle.isVisible())await toggle.click();if(flyout)await widget.locator('.hfe-flyout-show').waitFor();
 if(process.env.DEBUG_MENU)console.log(JSON.stringify(await widget.evaluate(w=>[...w.querySelectorAll('nav,.hfe-side,.hfe-nav-menu,.hfe-has-submenu-container')].map(e=>({tag:e.tagName,classes:e.className,style:e.getAttribute('style'),inert:!!e.closest('[inert]'),display:getComputedStyle(e).display,rect:{x:e.getBoundingClientRect().x,y:e.getBoundingClientRect().y,width:e.getBoundingClientRect().width,height:e.getBoundingClientRect().height}})))));
 const parents=widget.locator('.hfe-has-submenu-container > a');assert.equal(await parents.count(),2);for(let i=0;i<2;i++){const button=parents.nth(i);if(!flyout&&width===1440)await button.hover();else await button.click();assert.equal(await button.getAttribute('aria-expanded'),'true');}
 await page.waitForTimeout(350);await screenshot('open');const accessibility=await new AxeBuilder({page}).include('.elementor-widget-navigation-menu').withRules(['nested-interactive','aria-prohibited-attr']).analyze();assert.deepEqual(accessibility.violations.map(v=>v.id),[]);const geometry=await widget.locator('nav').evaluate(el=>{const r=el.getBoundingClientRect();return {x:r.x,width:r.width,height:r.height}});
 const expected=sourceChecks.find(r=>r.variant===record.variant&&r.width===width);assert.ok(expected,'Missing installed source geometry');for(const key of ['x','width','height'])assert.ok(Math.abs(geometry[key]-expected.geometry[key])<=1,'Geometry mismatch '+record.variant+' '+width+' '+key+': '+geometry[key]+' versus '+expected.geometry[key]);
 if(flyout){await widget.locator('.hfe-flyout-close').click();assert.equal(await widget.locator('.hfe-side').isVisible(),false);}else if(await toggle.isVisible())await toggle.click();else{for(const button of [...await parents.all()].reverse())if(await button.getAttribute('aria-expanded')==='true')await button.press('Escape');}
 const checks=(await verifyNavigation(page)).filter(r=>r.kind==='addon-navigation');assert.equal(checks.length,1);assert.equal(checks[0].status,'passed',JSON.stringify(checks));assert.equal(checks[0].disclosures,2);results.push({variant:record.variant,width,pixels,geometry,checks,accessibilityViolations:accessibility.violations.map(v=>v.id)});await context.close();
}await writeFile(path.join(artifact,process.env.VARIANT?'ultimate-variants-export-filtered.json':'ultimate-variants-export-check.json'),JSON.stringify(results,null,2));console.log(JSON.stringify(results));}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
